// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListDisputes The tenant's disputes, newest first
	// (GET /disputes)
	ListDisputes(w http.ResponseWriter, r *http.Request, params ListDisputesParams)
	// CreateDispute Open a dispute against a transaction
	// (POST /disputes)
	CreateDispute(w http.ResponseWriter, r *http.Request, params CreateDisputeParams)
	// GetDispute Current state and full event log
	// (GET /disputes/{disputeId})
	GetDispute(w http.ResponseWriter, r *http.Request, disputeId DisputeId)
	// UploadAttachment Upload a file to attach to an email
	// (POST /disputes/{disputeId}/attachments)
	UploadAttachment(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID)
	// GetAttachment Download an attachment
	// (GET /disputes/{disputeId}/attachments/{attachmentId})
	GetAttachment(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID, attachmentId openapi_types.UUID)
	// ListEmailTemplates The emails an analyst may compose for this dispute
	// (GET /disputes/{disputeId}/email-templates)
	ListEmailTemplates(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID)
	// ApplyDisputeEvent Apply a lifecycle event
	// (POST /disputes/{disputeId}/events)
	ApplyDisputeEvent(w http.ResponseWriter, r *http.Request, disputeId DisputeId, params ApplyDisputeEventParams)
	// ComposeEmail Compose and send an email from a template
	// (POST /disputes/{disputeId}/notices)
	ComposeEmail(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID)
	// GetNotice One communication to the customer, as composed
	// (GET /disputes/{disputeId}/notices/{noticeId})
	GetNotice(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID, noticeId int64)
	// ResendNotice Send an email again
	// (POST /disputes/{disputeId}/notices/{noticeId}/resend)
	ResendNotice(w http.ResponseWriter, r *http.Request, disputeId openapi_types.UUID, noticeId int64)
	// GetHealthz Liveness
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// DeleteSessions End every session matching a realm session id or a tenant's subject
	// (DELETE /internal/sessions)
	DeleteSessions(w http.ResponseWriter, r *http.Request, params DeleteSessionsParams)
	// DeleteSession Remove a session
	// (DELETE /internal/sessions/{sessionId})
	DeleteSession(w http.ResponseWriter, r *http.Request, sessionId openapi_types.UUID)
	// GetSession Fetch a session blob that has not expired
	// (GET /internal/sessions/{sessionId})
	GetSession(w http.ResponseWriter, r *http.Request, sessionId openapi_types.UUID)
	// PutSession Store or replace an opaque session blob
	// (PUT /internal/sessions/{sessionId})
	PutSession(w http.ResponseWriter, r *http.Request, sessionId openapi_types.UUID)
	// ListTenants Active tenants with what the sign-in page needs to find their realm
	// (GET /internal/tenants)
	ListTenants(w http.ResponseWriter, r *http.Request)
	// GetMyAvatar The signed-in analyst's picture
	// (GET /me/avatar)
	GetMyAvatar(w http.ResponseWriter, r *http.Request)
	// PutMyAvatar Replace the signed-in analyst's picture
	// (PUT /me/avatar)
	PutMyAvatar(w http.ResponseWriter, r *http.Request)
	// GetReadyz Readiness (database reachable)
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
	// GetTenant What the workbench shows about the signed-in analyst's organisation
	// (GET /tenant)
	GetTenant(w http.ResponseWriter, r *http.Request)
	// ListTenantKeys The tenant's own keys, live and revoked
	// (GET /tenant-keys)
	ListTenantKeys(w http.ResponseWriter, r *http.Request)
	// CreateTenantKey Issue a key for one of the tenant's systems
	// (POST /tenant-keys)
	CreateTenantKey(w http.ResponseWriter, r *http.Request)
	// RevokeTenantKey Revoke a key; takes effect on the next request
	// (DELETE /tenant-keys/{keyId})
	RevokeTenantKey(w http.ResponseWriter, r *http.Request, keyId openapi_types.UUID)
	// ListTenantTemplates The tenant's wording for each analyst email kind
	// (GET /tenant-templates)
	ListTenantTemplates(w http.ResponseWriter, r *http.Request)
	// DeleteTenantTemplate Revert one kind to the base wording
	// (DELETE /tenant-templates/{kind})
	DeleteTenantTemplate(w http.ResponseWriter, r *http.Request, kind NoticeKind)
	// PutTenantTemplate Set the tenant's wording for one kind
	// (PUT /tenant-templates/{kind})
	PutTenantTemplate(w http.ResponseWriter, r *http.Request, kind NoticeKind)
	// GetTenantLogo The organisation's logo
	// (GET /tenant/logo)
	GetTenantLogo(w http.ResponseWriter, r *http.Request)
	// PutTenantLogo Replace the organisation's logo
	// (PUT /tenant/logo)
	PutTenantLogo(w http.ResponseWriter, r *http.Request)
}

